right_code.class:
// Flexible dependency injection: pass resource to constructor
import java.util.Objects;

public class SpellChecker {
    private final Lexicon dictionary;

    // Dependency injected at construction time
    public SpellChecker(Lexicon dictionary) {
        this.dictionary = Objects.requireNonNull(dictionary);
    }

    public boolean isValid(String word) {
        return dictionary.contains(word);
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Production use:
        SpellChecker enChecker = new SpellChecker(new EnglishDictionary());
        // Unit test use:
        SpellChecker testChecker = new SpellChecker(new MockDictionary());
        // Multi-language use:
        SpellChecker frChecker = new SpellChecker(new FrenchDictionary());
    }
}
